"OLAYLAR_GEZGINLER:1805-08-19:0":{"b": ["Mungo Park 1805: Bamako – Koulikoro – Segu – Sansanding (Niger enişi)", "d566961f"], "d": ["Marşrut: Bamako → Koolikorro (Koulikoro) → Segu (Ségou) → Sansanding. Səyahətin hamısı xəritədə səyahət xətti kimi göstərilir.", "d67d385f"]},
"OLAYLAR_GEZGINLER:1811-11-05:0":{"b": ["Phari – Gyantse – Lhasa (Manning, 1811)", "0335f7eb"], "d": ["Marşrut: Phari (Pari-jong) → Gyantse (Giansu) → Lhasa. Səyahətin hamısı xəritədə səyahət xətti kimi göstərilir.", "973972f2"]},
