"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1094-06-15:0":{"b": ["El Sid Valensiyanı ələ keçirdi: Valensiya (El Sid) Knyazlığı quruldu", "f5b81beb"], "d": ["Rodrigo Díaz de Vivar (El Sid), mühasirədən sonra 15 iyun 1094-də Valensiyanın (Valensiya) nəzarətini ələ aldı; qazılıq məqamında İbn Cəhhafı saxladı. Valensiya, Mülukü-t-təvaif (Əndəlüs taifə əmirlikləri) qeydindən çıxıb Valensiya (El Sid) Knyazlığına keçdi.", "e51445ac"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1102-01-01:0":{"b": ["Mürabitlər Valensiyanı zəbt etdi", "ce05cefc"], "d": ["Rodriqonun 1099-dakı ölümündən sonra həyat yoldaşı Ximenanın əlindəki Valensiya 1102-də Mürabitlər tərəfindən zəbt edildi.", "8407a408"]},
"OLAYLAR_ORTACAG_IBERYA_MAGRIB:1102-05-05:0":{"b": ["Valensiya Mürabitlər tərəfindən zəbt edildi (1102)", "833a9c9a"], "d": ["El Sidin 1099-dakı ölümündən sonra şəhər dul həyat yoldaşı Ximenaya qalmışdı; Valensiya 1102-də Mürabitlər tərəfindən zəbt edildi. Valensiya bu tarixdə Valensiya (El Sid) Knyazlığından çıxıb Mürabitlər Dövlətinə keçir.", "a9ecdc4d"]},
